import { it, expect } from "vitest";
import { inputKindMismatch } from "../schema-java/input-kind";
it("diagnoses the screenshot SQL selected as Java without parsing it as Java", () => {
  expect(
    inputKindMismatch(
      "CREATE TABLE customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);",
      "java",
    ),
  ).toBe("inputSqlSelectedJava");
});
it("ignores comments/BOM and handles SELECT and COMMENT statements", () => {
  for (const sql of [
    "\uFEFF /* note */ CREATE TABLE t (id INT);",
    "-- comment\nSELECT id FROM t;",
    "COMMENT ON TABLE t IS 'class Example';",
  ]) {
    expect(inputKindMismatch(sql, "java")).toBe("inputSqlSelectedJava");
  }
});
it("recognizes Java in SQL mode, but not words inside SQL strings", () => {
  expect(
    inputKindMismatch("/* test */ public final class Customer {}", "sql"),
  ).toBe("inputJavaSelectedSql");
  expect(
    inputKindMismatch(
      "package com.example; public record Customer(Long id) {}",
      "sql",
    ),
  ).toBe("inputJavaSelectedSql");
  expect(
    inputKindMismatch("SELECT 'public class Customer' AS label", "sql"),
  ).toBeUndefined();
});
it("leaves valid input and ambiguous snippets for their actual parser", () => {
  expect(inputKindMismatch("CREATE TABLE t (id INT);", "sql")).toBeUndefined();
  expect(
    inputKindMismatch("public record Customer(Long id) {}", "java"),
  ).toBeUndefined();
  expect(
    inputKindMismatch("private final String value;", "sql"),
  ).toBeUndefined();
  expect(inputKindMismatch('{"tables":[]}', "metadata")).toBeUndefined();
  expect(inputKindMismatch("", "sql")).toBeUndefined();
});
